CREATE TABLE el_accounts(id TEXT PRIMARY KEY,org_id TEXT NOT NULL REFERENCES el_organizations(id),code TEXT NOT NULL,name TEXT NOT NULL,kind TEXT NOT NULL CHECK(kind IN ('asset','liability','equity','revenue','expense')),system_key TEXT,active INTEGER NOT NULL DEFAULT 1,is_demo INTEGER NOT NULL DEFAULT 0,UNIQUE(org_id,id),UNIQUE(org_id,code),UNIQUE(org_id,system_key));
CREATE TABLE el_financial_periods(id TEXT PRIMARY KEY,org_id TEXT NOT NULL REFERENCES el_organizations(id),name TEXT NOT NULL,starts_on TEXT NOT NULL,ends_on TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'open' CHECK(status IN ('open','closed')),is_demo INTEGER NOT NULL DEFAULT 0,CHECK(ends_on>=starts_on),UNIQUE(org_id,id));
CREATE TABLE el_journals(id TEXT PRIMARY KEY,org_id TEXT NOT NULL REFERENCES el_organizations(id),branch_id TEXT NOT NULL,period_id TEXT NOT NULL,date TEXT NOT NULL,reference TEXT NOT NULL,memo TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','posted')),source_type TEXT NOT NULL DEFAULT 'manual',source_id TEXT,reverse_of TEXT REFERENCES el_journals(id),created_by TEXT NOT NULL REFERENCES el_users(id),is_demo INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,posted_at TEXT,UNIQUE(org_id,id),UNIQUE(org_id,reference),UNIQUE(reverse_of),FOREIGN KEY(org_id,branch_id) REFERENCES el_branches(org_id,id),FOREIGN KEY(org_id,period_id) REFERENCES el_financial_periods(org_id,id));
CREATE TABLE el_journal_lines(id TEXT PRIMARY KEY,org_id TEXT NOT NULL,journal_id TEXT NOT NULL,account_id TEXT NOT NULL,debit INTEGER NOT NULL DEFAULT 0 CHECK(typeof(debit)='integer' AND debit>=0),credit INTEGER NOT NULL DEFAULT 0 CHECK(typeof(credit)='integer' AND credit>=0),description TEXT NOT NULL DEFAULT '',is_demo INTEGER NOT NULL DEFAULT 0,CHECK((debit>0 AND credit=0) OR (credit>0 AND debit=0)),FOREIGN KEY(org_id,journal_id) REFERENCES el_journals(org_id,id),FOREIGN KEY(org_id,account_id) REFERENCES el_accounts(org_id,id));
CREATE TRIGGER el_journal_post_guard BEFORE UPDATE OF status ON el_journals WHEN NEW.status='posted' BEGIN
SELECT CASE WHEN OLD.status<>'draft' THEN RAISE(ABORT,'Journal already posted') END;
SELECT CASE WHEN (SELECT count(*) FROM el_journal_lines WHERE journal_id=NEW.id)<2 OR (SELECT COALESCE(sum(debit-credit),1) FROM el_journal_lines WHERE journal_id=NEW.id)<>0 THEN RAISE(ABORT,'Journal must have balanced debit and credit lines') END;
SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM el_financial_periods WHERE id=NEW.period_id AND org_id=NEW.org_id AND status='open' AND starts_on<=NEW.date AND ends_on>=NEW.date) THEN RAISE(ABORT,'Financial period is closed or date is outside period') END;
END;
CREATE TRIGGER el_journal_immutable BEFORE UPDATE ON el_journals WHEN OLD.status='posted' BEGIN SELECT RAISE(ABORT,'Posted journals are immutable; create a reversal'); END;
CREATE TRIGGER el_journal_no_delete BEFORE DELETE ON el_journals WHEN OLD.status='posted' AND OLD.is_demo=0 BEGIN SELECT RAISE(ABORT,'Posted journals cannot be deleted'); END;
CREATE TRIGGER el_journal_line_insert_guard BEFORE INSERT ON el_journal_lines BEGIN SELECT CASE WHEN (SELECT status FROM el_journals WHERE id=NEW.journal_id)<>'draft' THEN RAISE(ABORT,'Posted journal lines are immutable') END; END;
CREATE TRIGGER el_journal_line_update_guard BEFORE UPDATE ON el_journal_lines BEGIN SELECT CASE WHEN (SELECT status FROM el_journals WHERE id=OLD.journal_id)='posted' THEN RAISE(ABORT,'Posted journal lines are immutable') END; END;
CREATE TRIGGER el_journal_line_delete_guard BEFORE DELETE ON el_journal_lines WHEN OLD.is_demo=0 BEGIN SELECT CASE WHEN (SELECT status FROM el_journals WHERE id=OLD.journal_id)='posted' THEN RAISE(ABORT,'Posted journal lines are immutable') END; END;
CREATE TABLE el_invoices(id TEXT PRIMARY KEY,org_id TEXT NOT NULL,branch_id TEXT NOT NULL,student_id TEXT NOT NULL,number TEXT NOT NULL,date TEXT NOT NULL,due_date TEXT NOT NULL,currency TEXT NOT NULL DEFAULT 'EGP',discount INTEGER NOT NULL DEFAULT 0 CHECK(discount>=0),total INTEGER NOT NULL CHECK(typeof(total)='integer' AND total>0),status TEXT NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','issued','void')),journal_id TEXT,created_by TEXT NOT NULL REFERENCES el_users(id),is_demo INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(org_id,id),UNIQUE(org_id,number),CHECK(due_date>=date),FOREIGN KEY(org_id,branch_id) REFERENCES el_branches(org_id,id),FOREIGN KEY(org_id,student_id) REFERENCES el_students(org_id,id),FOREIGN KEY(org_id,journal_id) REFERENCES el_journals(org_id,id));
CREATE TABLE el_invoice_items(id TEXT PRIMARY KEY,org_id TEXT NOT NULL,invoice_id TEXT NOT NULL,description TEXT NOT NULL,quantity INTEGER NOT NULL CHECK(quantity>0),unit_price INTEGER NOT NULL CHECK(typeof(unit_price)='integer' AND unit_price>=0),is_demo INTEGER NOT NULL DEFAULT 0,FOREIGN KEY(org_id,invoice_id) REFERENCES el_invoices(org_id,id));
CREATE TABLE el_payments(id TEXT PRIMARY KEY,org_id TEXT NOT NULL,branch_id TEXT NOT NULL,invoice_id TEXT NOT NULL,date TEXT NOT NULL,amount INTEGER NOT NULL CHECK(typeof(amount)='integer' AND amount>0),method TEXT NOT NULL CHECK(method IN ('cash','bank','electronic')),reference TEXT NOT NULL,idempotency_key TEXT NOT NULL,kind TEXT NOT NULL DEFAULT 'receipt' CHECK(kind IN ('receipt','refund')),refund_of TEXT,reason TEXT NOT NULL DEFAULT '',journal_id TEXT NOT NULL,created_by TEXT NOT NULL REFERENCES el_users(id),is_demo INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(org_id,id),UNIQUE(org_id,idempotency_key),FOREIGN KEY(org_id,branch_id) REFERENCES el_branches(org_id,id),FOREIGN KEY(org_id,invoice_id) REFERENCES el_invoices(org_id,id),FOREIGN KEY(org_id,journal_id) REFERENCES el_journals(org_id,id),FOREIGN KEY(org_id,refund_of) REFERENCES el_payments(org_id,id));
CREATE TRIGGER el_payment_guard BEFORE INSERT ON el_payments BEGIN
SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM el_invoices WHERE id=NEW.invoice_id AND org_id=NEW.org_id AND branch_id=NEW.branch_id AND status='issued') THEN RAISE(ABORT,'Invoice is not issued') END;
SELECT CASE WHEN NEW.kind='receipt' AND NEW.amount>(SELECT total-COALESCE((SELECT sum(CASE WHEN kind='receipt' THEN amount ELSE -amount END) FROM el_payments WHERE invoice_id=NEW.invoice_id),0) FROM el_invoices WHERE id=NEW.invoice_id) THEN RAISE(ABORT,'Payment exceeds outstanding invoice balance') END;
SELECT CASE WHEN NEW.kind='refund' AND NOT EXISTS(SELECT 1 FROM el_payments p WHERE p.id=NEW.refund_of AND p.kind='receipt' AND p.invoice_id=NEW.invoice_id AND p.amount-COALESCE((SELECT sum(amount) FROM el_payments WHERE refund_of=p.id),0)>=NEW.amount) THEN RAISE(ABORT,'Refund exceeds original unrefunded payment') END;
END;
CREATE TRIGGER el_payment_immutable BEFORE UPDATE ON el_payments BEGIN SELECT RAISE(ABORT,'Recorded payments are immutable; record a refund'); END;
CREATE TRIGGER el_payment_no_delete BEFORE DELETE ON el_payments WHEN OLD.is_demo=0 BEGIN SELECT RAISE(ABORT,'Recorded payments cannot be deleted'); END;
CREATE TRIGGER el_invoice_issued_guard BEFORE UPDATE ON el_invoices WHEN OLD.status='issued' BEGIN
SELECT CASE WHEN NEW.status<>'void' OR NEW.total<>OLD.total OR NEW.student_id<>OLD.student_id OR NEW.branch_id<>OLD.branch_id OR NEW.discount<>OLD.discount OR NEW.number<>OLD.number OR NEW.date<>OLD.date OR NEW.due_date<>OLD.due_date OR NEW.currency<>OLD.currency OR NEW.journal_id<>OLD.journal_id THEN RAISE(ABORT,'Issued invoice is immutable; use an auditable reversal') END;
SELECT CASE WHEN COALESCE((SELECT sum(CASE WHEN kind='receipt' THEN amount ELSE -amount END) FROM el_payments WHERE invoice_id=OLD.id),0)<>0 THEN RAISE(ABORT,'Refund receipts before voiding invoice') END;
END;
CREATE TRIGGER el_invoice_items_insert BEFORE INSERT ON el_invoice_items BEGIN SELECT CASE WHEN (SELECT status FROM el_invoices WHERE id=NEW.invoice_id)<>'draft' THEN RAISE(ABORT,'Issued invoice items are immutable') END; END;
CREATE TRIGGER el_invoice_items_update BEFORE UPDATE ON el_invoice_items BEGIN SELECT CASE WHEN (SELECT status FROM el_invoices WHERE id=OLD.invoice_id)<>'draft' THEN RAISE(ABORT,'Issued invoice items are immutable') END; END;
CREATE TRIGGER el_invoice_items_delete BEFORE DELETE ON el_invoice_items WHEN OLD.is_demo=0 BEGIN SELECT CASE WHEN (SELECT status FROM el_invoices WHERE id=OLD.invoice_id)<>'draft' THEN RAISE(ABORT,'Issued invoice items are immutable') END; END;
CREATE TABLE el_expenses(id TEXT PRIMARY KEY,org_id TEXT NOT NULL,branch_id TEXT NOT NULL,date TEXT NOT NULL,category TEXT NOT NULL,description TEXT NOT NULL,amount INTEGER NOT NULL CHECK(typeof(amount)='integer' AND amount>0),method TEXT NOT NULL CHECK(method IN ('cash','bank','payable')),status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','approved','rejected')),created_by TEXT NOT NULL REFERENCES el_users(id),approved_by TEXT REFERENCES el_users(id),journal_id TEXT,is_demo INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(org_id,id),FOREIGN KEY(org_id,branch_id) REFERENCES el_branches(org_id,id),FOREIGN KEY(org_id,journal_id) REFERENCES el_journals(org_id,id));
CREATE TRIGGER el_expense_guard BEFORE UPDATE ON el_expenses BEGIN SELECT CASE WHEN OLD.status<>'pending' THEN RAISE(ABORT,'Finalized expense is immutable') END;SELECT CASE WHEN NEW.status='approved' AND NEW.created_by=NEW.approved_by THEN RAISE(ABORT,'Expense approver must be a different user') END; END;
CREATE TABLE el_compensation(id TEXT PRIMARY KEY,org_id TEXT NOT NULL,branch_id TEXT NOT NULL,teacher_id TEXT NOT NULL,type TEXT NOT NULL CHECK(type IN ('fixed','hourly','per_session','per_student','revenue_percent','hybrid')),base INTEGER NOT NULL DEFAULT 0 CHECK(typeof(base)='integer' AND base>=0),rate INTEGER NOT NULL DEFAULT 0 CHECK(typeof(rate)='integer' AND rate>=0),percent INTEGER NOT NULL DEFAULT 0 CHECK(percent BETWEEN 0 AND 100),status TEXT NOT NULL DEFAULT 'active' CHECK(status IN ('active','inactive')),is_demo INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(org_id,id),FOREIGN KEY(org_id,branch_id) REFERENCES el_branches(org_id,id),FOREIGN KEY(org_id,teacher_id) REFERENCES el_teachers(org_id,id));
CREATE UNIQUE INDEX el_compensation_active ON el_compensation(org_id,teacher_id) WHERE status='active';
CREATE TABLE el_payroll(id TEXT PRIMARY KEY,org_id TEXT NOT NULL,branch_id TEXT NOT NULL,teacher_id TEXT NOT NULL,month TEXT NOT NULL,compensation_id TEXT NOT NULL,calculation_json TEXT NOT NULL,base_amount INTEGER NOT NULL,bonus INTEGER NOT NULL DEFAULT 0 CHECK(bonus>=0),deduction INTEGER NOT NULL DEFAULT 0 CHECK(deduction>=0),total INTEGER NOT NULL CHECK(typeof(total)='integer' AND total>=0),status TEXT NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','approved','paid')),created_by TEXT NOT NULL REFERENCES el_users(id),approved_by TEXT REFERENCES el_users(id),paid_by TEXT REFERENCES el_users(id),journal_id TEXT,is_demo INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(org_id,id),UNIQUE(org_id,teacher_id,month),FOREIGN KEY(org_id,branch_id) REFERENCES el_branches(org_id,id),FOREIGN KEY(org_id,teacher_id) REFERENCES el_teachers(org_id,id),FOREIGN KEY(org_id,compensation_id) REFERENCES el_compensation(org_id,id),FOREIGN KEY(org_id,journal_id) REFERENCES el_journals(org_id,id));
CREATE TRIGGER el_payroll_guard BEFORE UPDATE ON el_payroll BEGIN
SELECT CASE WHEN NEW.total<>OLD.total OR NEW.base_amount<>OLD.base_amount OR NEW.calculation_json<>OLD.calculation_json OR NEW.bonus<>OLD.bonus OR NEW.deduction<>OLD.deduction THEN RAISE(ABORT,'Calculated payroll is immutable') END;
SELECT CASE WHEN NOT((OLD.status='draft' AND NEW.status='approved') OR (OLD.status='approved' AND NEW.status='paid')) THEN RAISE(ABORT,'Invalid payroll transition') END;
SELECT CASE WHEN NEW.status='approved' AND NEW.approved_by=NEW.created_by THEN RAISE(ABORT,'Payroll approver must be a different user') END;
SELECT CASE WHEN NEW.status='paid' AND (NEW.paid_by=NEW.approved_by OR NEW.paid_by=NEW.created_by) THEN RAISE(ABORT,'Payroll payment requires a separate finance user') END;
END;
CREATE INDEX el_journals_ledger ON el_journals(org_id,status,date,branch_id);
CREATE INDEX el_journal_account ON el_journal_lines(org_id,account_id,journal_id);
CREATE INDEX el_invoices_lookup ON el_invoices(org_id,branch_id,status,due_date);
CREATE INDEX el_payments_invoice ON el_payments(org_id,invoice_id,date);
CREATE INDEX el_expenses_lookup ON el_expenses(org_id,branch_id,status,date);
CREATE INDEX el_payroll_lookup ON el_payroll(org_id,branch_id,status,month);
CREATE TRIGGER el_period_overlap BEFORE INSERT ON el_financial_periods BEGIN SELECT CASE WHEN EXISTS(SELECT 1 FROM el_financial_periods WHERE org_id=NEW.org_id AND starts_on<=NEW.ends_on AND ends_on>=NEW.starts_on) THEN RAISE(ABORT,'Financial period overlaps an existing period') END; END;
CREATE TABLE el_invoice_teacher_shares(id TEXT PRIMARY KEY,org_id TEXT NOT NULL,invoice_id TEXT NOT NULL,teacher_id TEXT NOT NULL,amount INTEGER NOT NULL CHECK(typeof(amount)='integer' AND amount>0),is_demo INTEGER NOT NULL DEFAULT 0,UNIQUE(invoice_id,teacher_id),FOREIGN KEY(org_id,invoice_id) REFERENCES el_invoices(org_id,id),FOREIGN KEY(org_id,teacher_id) REFERENCES el_teachers(org_id,id));
CREATE TRIGGER el_teacher_share_guard BEFORE INSERT ON el_invoice_teacher_shares BEGIN
SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM el_invoices WHERE id=NEW.invoice_id AND status='draft') THEN RAISE(ABORT,'Invoice allocations are locked after issue') END;
SELECT CASE WHEN NEW.amount+COALESCE((SELECT sum(amount) FROM el_invoice_teacher_shares WHERE invoice_id=NEW.invoice_id),0)>(SELECT total FROM el_invoices WHERE id=NEW.invoice_id) THEN RAISE(ABORT,'Teacher allocations exceed invoice total') END;
END;
CREATE TRIGGER el_teacher_share_update_guard BEFORE UPDATE ON el_invoice_teacher_shares BEGIN SELECT RAISE(ABORT,'Replace draft allocations instead of editing'); END;
CREATE TRIGGER el_teacher_share_delete_guard BEFORE DELETE ON el_invoice_teacher_shares WHEN OLD.is_demo=0 BEGIN SELECT CASE WHEN (SELECT status FROM el_invoices WHERE id=OLD.invoice_id)<>'draft' THEN RAISE(ABORT,'Invoice allocations are locked after issue') END; END;
CREATE INDEX el_teacher_share_teacher ON el_invoice_teacher_shares(org_id,teacher_id,invoice_id);
CREATE INDEX el_journal_lines_parent ON el_journal_lines(journal_id);
CREATE INDEX el_invoice_items_parent ON el_invoice_items(invoice_id);
CREATE INDEX el_payments_balance ON el_payments(invoice_id,kind);
CREATE INDEX el_payments_refunds ON el_payments(refund_of);
CREATE INDEX el_period_lookup ON el_financial_periods(org_id,status,starts_on,ends_on);
CREATE INDEX el_finance_demo_invoice ON el_invoices(org_id,is_demo);
CREATE INDEX el_finance_demo_account ON el_accounts(org_id,is_demo);
CREATE INDEX el_finance_demo_period ON el_financial_periods(org_id,is_demo);
CREATE UNIQUE INDEX el_journal_source ON el_journals(org_id,source_type,source_id);
CREATE TRIGGER el_invoice_no_delete BEFORE DELETE ON el_invoices WHEN OLD.status<>'draft' AND OLD.is_demo=0 BEGIN SELECT RAISE(ABORT,'Finalized invoices cannot be deleted'); END;
CREATE TRIGGER el_invoice_final_immutable BEFORE UPDATE ON el_invoices WHEN OLD.status='void' BEGIN SELECT RAISE(ABORT,'Voided invoice is immutable'); END;
CREATE TRIGGER el_payroll_no_delete BEFORE DELETE ON el_payroll WHEN OLD.is_demo=0 BEGIN SELECT RAISE(ABORT,'Payroll cannot be deleted'); END;
CREATE TRIGGER el_expense_no_delete BEFORE DELETE ON el_expenses WHEN OLD.status<>'pending' AND OLD.is_demo=0 BEGIN SELECT RAISE(ABORT,'Finalized expense cannot be deleted'); END;
CREATE TABLE el_installments(id TEXT PRIMARY KEY,org_id TEXT NOT NULL,invoice_id TEXT NOT NULL,due_date TEXT NOT NULL,amount INTEGER NOT NULL CHECK(typeof(amount)='integer' AND amount>0),is_demo INTEGER NOT NULL DEFAULT 0,FOREIGN KEY(org_id,invoice_id) REFERENCES el_invoices(org_id,id));
CREATE INDEX el_installments_invoice ON el_installments(invoice_id,due_date);
CREATE TRIGGER el_installment_insert BEFORE INSERT ON el_installments BEGIN SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM el_invoices WHERE id=NEW.invoice_id AND org_id=NEW.org_id AND status='draft' AND date<=NEW.due_date AND due_date>=NEW.due_date) THEN RAISE(ABORT,'Installment date must be within draft invoice dates') END; END;
CREATE TRIGGER el_installment_update BEFORE UPDATE ON el_installments BEGIN SELECT RAISE(ABORT,'Replace draft installment plan instead'); END;
CREATE TRIGGER el_installment_delete BEFORE DELETE ON el_installments WHEN OLD.is_demo=0 BEGIN SELECT CASE WHEN (SELECT status FROM el_invoices WHERE id=OLD.invoice_id)<>'draft' THEN RAISE(ABORT,'Issued installment plan is immutable') END; END;
CREATE TRIGGER el_invoice_issue_checks BEFORE UPDATE OF status ON el_invoices WHEN NEW.status='issued' BEGIN
SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM el_invoice_items WHERE invoice_id=NEW.id) THEN RAISE(ABORT,'Invoice needs line items') END;
SELECT CASE WHEN (SELECT sum(quantity*unit_price) FROM el_invoice_items WHERE invoice_id=NEW.id)-NEW.discount<>NEW.total THEN RAISE(ABORT,'Invoice total does not match line items') END;
SELECT CASE WHEN EXISTS(SELECT 1 FROM el_installments WHERE invoice_id=NEW.id) AND (SELECT sum(amount) FROM el_installments WHERE invoice_id=NEW.id)<>NEW.total THEN RAISE(ABORT,'Installments must equal invoice total') END;
END;
CREATE TABLE el_reconciliations(id TEXT PRIMARY KEY,org_id TEXT NOT NULL,branch_id TEXT NOT NULL,account_id TEXT NOT NULL,statement_date TEXT NOT NULL,opening_balance INTEGER NOT NULL,closing_balance INTEGER NOT NULL,reference TEXT NOT NULL,created_by TEXT NOT NULL REFERENCES el_users(id),created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,is_demo INTEGER NOT NULL DEFAULT 0,UNIQUE(org_id,id),FOREIGN KEY(org_id,branch_id) REFERENCES el_branches(org_id,id),FOREIGN KEY(org_id,account_id) REFERENCES el_accounts(org_id,id));
CREATE TABLE el_reconciliation_lines(id TEXT PRIMARY KEY,org_id TEXT NOT NULL,reconciliation_id TEXT NOT NULL,line_id TEXT NOT NULL UNIQUE REFERENCES el_journal_lines(id),is_demo INTEGER NOT NULL DEFAULT 0,FOREIGN KEY(org_id,reconciliation_id) REFERENCES el_reconciliations(org_id,id));
CREATE INDEX el_reconciliations_lookup ON el_reconciliations(org_id,branch_id,statement_date);
CREATE TRIGGER el_reconciliation_immutable BEFORE UPDATE ON el_reconciliations BEGIN SELECT RAISE(ABORT,'Reconciliations are immutable'); END;
CREATE TRIGGER el_reconciliation_no_delete BEFORE DELETE ON el_reconciliations WHEN OLD.is_demo=0 BEGIN SELECT RAISE(ABORT,'Reconciliations cannot be deleted'); END;
CREATE TRIGGER el_reconciliation_line_update BEFORE UPDATE ON el_reconciliation_lines BEGIN SELECT RAISE(ABORT,'Reconciliations are immutable'); END;
CREATE TRIGGER el_reconciliation_line_delete BEFORE DELETE ON el_reconciliation_lines WHEN OLD.is_demo=0 BEGIN SELECT RAISE(ABORT,'Reconciliations cannot be deleted'); END;
CREATE TABLE el_expense_payments(id TEXT PRIMARY KEY,org_id TEXT NOT NULL,branch_id TEXT NOT NULL,expense_id TEXT NOT NULL,date TEXT NOT NULL,amount INTEGER NOT NULL CHECK(typeof(amount)='integer' AND amount>0),method TEXT NOT NULL CHECK(method IN ('cash','bank')),reference TEXT NOT NULL,idempotency_key TEXT NOT NULL,journal_id TEXT NOT NULL,created_by TEXT NOT NULL REFERENCES el_users(id),is_demo INTEGER NOT NULL DEFAULT 0,UNIQUE(org_id,idempotency_key),FOREIGN KEY(org_id,expense_id) REFERENCES el_expenses(org_id,id),FOREIGN KEY(org_id,journal_id) REFERENCES el_journals(org_id,id),FOREIGN KEY(org_id,branch_id) REFERENCES el_branches(org_id,id));
CREATE INDEX el_expense_payments_parent ON el_expense_payments(expense_id);
CREATE TRIGGER el_expense_payment_guard BEFORE INSERT ON el_expense_payments BEGIN SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM el_expenses e WHERE e.id=NEW.expense_id AND e.org_id=NEW.org_id AND e.branch_id=NEW.branch_id AND e.method='payable' AND e.status='approved' AND NEW.date>=e.date AND NEW.amount<=e.amount-COALESCE((SELECT sum(amount) FROM el_expense_payments WHERE expense_id=e.id),0)) THEN RAISE(ABORT,'Settlement exceeds approved payable balance') END; END;
CREATE TRIGGER el_expense_payment_immutable BEFORE UPDATE ON el_expense_payments BEGIN SELECT RAISE(ABORT,'Settlements are immutable'); END;
CREATE TRIGGER el_expense_payment_no_delete BEFORE DELETE ON el_expense_payments WHEN OLD.is_demo=0 BEGIN SELECT RAISE(ABORT,'Settlements cannot be deleted'); END;
